from __future__ import annotations
import json,math,statistics
from collections import defaultdict
from datetime import datetime,timezone
from pathlib import Path
from typing import Any
try:from paper_position_tracker import connect,DB_PATH
except ModuleNotFoundError:from scripts.paper_position_tracker import connect,DB_PATH
ROOT=Path(__file__).resolve().parents[1];STATS=ROOT/'PAPER_RESEARCH/STATS'
def sample_quality(n:int)->str:return 'HIGHER_CONFIDENCE' if n>=100 else 'MEDIUM' if n>=50 else 'LOW' if n>=20 else 'INSUFFICIENT'
def metrics(rows:list[dict],unique_episodes:int|None=None,unique_asset_episodes:int|None=None)->dict[str,Any]:
 vals=[float(x['net_return_pct']) for x in rows];wins=[x for x in vals if x>0];loss=[x for x in vals if x<0];n=len(vals);wr=len(wins)/n*100 if n else 0;aw=statistics.mean(wins) if wins else 0;al=abs(statistics.mean(loss)) if loss else 0;pay=aw/al if al else None;be=100/(1+pay) if pay is not None else None;ev=(wr/100)*aw-(1-wr/100)*al if n else 0;gp=sum(wins);gl=abs(sum(loss));pf=gp/gl if gl else None;equity=0;peak=0;dd=0;streak=longest=0
 for v in vals:equity+=v;peak=max(peak,equity);dd=min(dd,equity-peak);streak=streak+1 if v<0 else 0;longest=max(longest,streak)
 episodes=n if unique_episodes is None else unique_episodes;asset_episodes=episodes if unique_asset_episodes is None else unique_asset_episodes;q=sample_quality(episodes);status='INSUFFICIENT_SAMPLE' if episodes<20 else 'POSITIVE_EDGE_OBSERVED' if ev>0 else 'NEGATIVE_EDGE'
 return {'sample_size':n,'variant_trade_count':n,'unique_setup_episode_count':episodes,'unique_asset_episode_count':asset_episodes,'wins':len(wins),'losses':len(loss),'win_rate':round(wr,4),'average_win_pct':round(aw,4),'average_loss_pct':round(al,4),'payoff_ratio':None if pay is None else round(pay,4),'break_even_win_rate':None if be is None else round(be,4),'expected_value_pct':round(ev,4),'profit_factor':None if pf is None else round(pf,4),'median_return_pct':round(statistics.median(vals),4) if vals else 0,'standard_deviation_pct':round(statistics.pstdev(vals),4) if len(vals)>1 else 0,'maximum_drawdown_pct':round(dd,4),'longest_loss_streak':longest,'median_holding_hours':round(statistics.median([x['holding_hours'] for x in rows]),4) if rows else 0,'average_mfe_pct':round(statistics.mean([x['mfe_pct'] for x in rows]),4) if rows else 0,'average_mae_pct':round(statistics.mean([x['mae_pct'] for x in rows]),4) if rows else 0,'sample_quality':q,'status':status,'warnings':['CORRELATED_VARIANT_SAMPLE'] if n>episodes else []}
def update_stats(db=None)->list[dict]:
 own=db is None;db=db or connect();groups=defaultdict(list);combos=defaultdict(list)
 for row in db.execute("SELECT t.*,s.setup_episode_id FROM paper_trades t JOIN paper_signals s ON s.signal_id=t.signal_id WHERE t.status='CLOSED' ORDER BY t.exit_timestamp,t.trade_id"):
  d=dict(row);groups[(d['strategy_name'],d['strategy_variant'])].append(d);combos[d['source_modules']].append(d)
 now=datetime.now(timezone.utc).isoformat();out=[];db.execute('DELETE FROM paper_strategy_stats');db.execute('DELETE FROM paper_module_combinations')
 for (s,v),rows in sorted(groups.items()):
  episodes=len({r['setup_episode_id'] for r in rows});asset_episodes=len({(r['asset'],r['setup_episode_id']) for r in rows});x=metrics(rows,episodes,asset_episodes);out.append({'strategy':s,'variant':v,**x});db.execute('''INSERT INTO paper_strategy_stats(strategy_name,strategy_variant,sample_size,wins,losses,win_rate,average_win_pct,average_loss_pct,payoff_ratio,expected_value_pct,break_even_win_rate,profit_factor,maximum_drawdown_pct,longest_loss_streak,median_holding_hours,average_mfe_pct,average_mae_pct,sample_quality,status,updated_at,variant_trade_count,unique_setup_episode_count,unique_asset_episode_count) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)''',(s,v,x['sample_size'],x['wins'],x['losses'],x['win_rate'],x['average_win_pct'],x['average_loss_pct'],x['payoff_ratio'],x['expected_value_pct'],x['break_even_win_rate'],x['profit_factor'],x['maximum_drawdown_pct'],x['longest_loss_streak'],x['median_holding_hours'],x['average_mfe_pct'],x['average_mae_pct'],x['sample_quality'],x['status'],now,x['variant_trade_count'],x['unique_setup_episode_count'],x['unique_asset_episode_count']))
 for combo,rows in combos.items():
  episodes=len({r['setup_episode_id'] for r in rows});x=metrics(rows,episodes,len({(r['asset'],r['setup_episode_id']) for r in rows}));db.execute('INSERT INTO paper_module_combinations VALUES(?,?,?,?,?)',(combo,episodes,x['expected_value_pct'],x['profit_factor'],now))
 db.commit();
 if own:db.close()
 return out
def write_comparison(stats:list[dict],db=None)->tuple[Path,Path]:
 own=db is None;db=db or connect();totals=dict(db.execute('''SELECT count(*) variant_trade_count,count(DISTINCT s.setup_episode_id) unique_setup_episode_count,count(DISTINCT t.asset||'|'||s.setup_episode_id) unique_asset_episode_count,sum(CASE WHEN t.status='CLOSED' THEN 1 ELSE 0 END) closed_variant_trade_count,count(DISTINCT CASE WHEN t.status='CLOSED' THEN s.setup_episode_id END) closed_unique_episode_count FROM paper_trades t JOIN paper_signals s ON s.signal_id=t.signal_id''').fetchone());warnings=['CORRELATED_VARIANT_SAMPLE'] if totals['variant_trade_count']>totals['unique_setup_episode_count'] else [];STATS.mkdir(parents=True,exist_ok=True);payload={'generated_at_utc':datetime.now(timezone.utc).isoformat(),'labels':['RESEARCH_ONLY','PAPER_ONLY','NO_REAL_ORDERS'],'totals':totals,'warnings':warnings,'strategies':stats};jp=STATS/'latest_strategy_comparison.json';mp=STATS/'latest_strategy_comparison.md';jp.write_text(json.dumps(payload,indent=2,sort_keys=True,allow_nan=False)+'\n');lines=['# Paper Strategy Comparison','','PAPER_ONLY | RESEARCH_ONLY | NO_REAL_ORDERS','',f"- TOTAL VARIANT TRADES: {totals['variant_trade_count']}",f"- UNIQUE SETUP EPISODES: {totals['unique_setup_episode_count']}",f"- CLOSED VARIANT TRADES: {totals['closed_variant_trade_count']}",f"- CLOSED UNIQUE EPISODES: {totals['closed_unique_episode_count']}"]+(["- Warning: CORRELATED_VARIANT_SAMPLE"] if warnings else [])+['']
 for x in stats:lines += [f"## {x['strategy']} / {x['variant']}",f"- Variant closed trades: {x['variant_trade_count']} | Unique episodes: {x['unique_setup_episode_count']}",f"- WR: {x['win_rate']}% | Avg win/loss: {x['average_win_pct']}% / -{x['average_loss_pct']}%",f"- Payoff: {x['payoff_ratio']} | EV: {x['expected_value_pct']}% | PF: {x['profit_factor']} | Max DD: {x['maximum_drawdown_pct']}%",f"- Sample: {x['sample_quality']}"+(" | CORRELATED_VARIANT_SAMPLE" if x['warnings'] else ''),'']
 mp.write_text('\n'.join(lines)+'\n');return jp,mp
